REPLACE INTO gramma (grammaid, structure, explanation, example, grammar_type, vietnamese_pronunciation) VALUES
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000001','-','')), 'N は N です', 'Trợ từ は dùng để đánh dấu chủ đề của câu.', 'わたしは学生です。', 'particle', 'wa'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000002','-','')), 'N を V', 'Trợ từ を dùng để đánh dấu tân ngữ trực tiếp.', 'ごはんを食べます。', 'particle', 'wo'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000003','-','')), 'N が N です', 'Trợ từ が dùng để đánh dấu chủ ngữ.', 'あの人が先生です。', 'particle', 'ga'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000004','-','')), 'N に N があります', 'Diễn tả sự tồn tại của vật ở một địa điểm.', '山に水があります。', 'pattern', 'ni'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000005','-','')), 'V ます', 'Thể lịch sự của động từ.', '毎日日本語を勉強します。', 'conjugation', 'masu'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000006','-','')), 'V ません', 'Thể phủ định lịch sự của động từ.', 'お酒を飲みません。', 'conjugation', 'masen'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000007','-','')), 'V ている', 'Diễn tả hành động đang diễn ra hoặc trạng thái tiếp diễn.', '本を読んでいます。', 'conjugation', 'te iru'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000008','-','')), 'V たい', 'Diễn tả mong muốn làm gì đó của người nói.', '水を飲みたいです。', 'conjugation', 'tai'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000009','-','')), 'V ませんか', 'Lời mời, rủ ai đó cùng làm gì.', '一緒に行きませんか。', 'pattern', 'masen ka'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000010','-','')), 'V ましょう', 'Đề nghị cùng làm gì đó.', '行きましょう。', 'pattern', 'mashou'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000011','-','')), 'V てもいいです', 'Diễn tả sự cho phép làm gì đó.', 'ここに座ってもいいです。', 'pattern', 'temo ii desu'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000012','-','')), 'V てはいけません', 'Diễn tả sự cấm đoán, không được làm.', 'ここで写真を撮ってはいけません。', 'pattern', 'te wa ikemasen'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000013','-','')), '～から', 'Trợ từ chỉ nguyên nhân, lý do.', '時間がないから、急ぎましょう。', 'particle', 'kara'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000014','-','')), '～が、～', 'Nối hai câu mang nghĩa tương phản.', '高いですが、おいしいです。', 'conjunction', 'ga'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000015','-','')), 'A より B', 'Dùng để so sánh A và B.', '犬より猫が好きです。', 'particle', 'yori'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000016','-','')), 'N と N', 'Liên kết các danh từ với nghĩa "và".', '犬と猫がいます。', 'particle', 'to'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000017','-','')), 'N へ', 'Trợ từ chỉ hướng di chuyển.', '日本へ行きます。', 'particle', 'e'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000018','-','')), 'N で', 'Trợ từ chỉ phương tiện hoặc địa điểm hành động.', 'バスで行きます。', 'particle', 'de'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000019','-','')), 'V ながら', 'Diễn tả hai hành động diễn ra đồng thời.', '音楽を聞きながら勉強します。', 'pattern', 'nagara'),
  (UNHEX(REPLACE('30000000-0000-0000-0000-000000000020','-','')), 'V たことがある', 'Diễn tả đã từng có trải nghiệm làm gì.', '日本に行ったことがあります。', 'pattern', 'ta koto ga aru');
REPLACE INTO sample_sentence (sample_sentence_id, japanese_text, vietnamese_meaning, vietnamese_pronunciation) VALUES
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000001','-','')), 'わたしは学生です。', 'Tôi là học sinh.', 'Watashi wa gakusei desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000002','-','')), '毎朝水を飲みます。', 'Mỗi sáng tôi uống nước.', 'Maiasa mizu wo nomimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000003','-','')), '山の上に火があります。', 'Trên núi có lửa.', 'Yama no ue ni hi ga arimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000004','-','')), '日本語を勉強しています。', 'Tôi đang học tiếng Nhật.', 'Nihongo wo benkyou shiteimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000005','-','')), 'この本は大きいです。', 'Cuốn sách này lớn.', 'Kono hon wa ookii desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000006','-','')), '火曜日に先生に会います。', 'Thứ Ba tôi gặp giáo viên.', 'Kayoubi ni sensei ni aimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000007','-','')), '私は毎日日本語を勉強します。', 'Tôi học tiếng Nhật mỗi ngày.', 'Watashi wa mainichi nihongo wo benkyou shimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000008','-','')), '友達と映画を見ました。', 'Tôi đã xem phim với bạn.', 'Tomodachi to eiga wo mimashita.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000009','-','')), '学校は駅の前にあります。', 'Trường học nằm ở trước nhà ga.', 'Gakkou wa eki no mae ni arimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000010','-','')), '今日は天気がいいですね。', 'Hôm nay thời tiết đẹp nhỉ.', 'Kyou wa tenki ga ii desu ne.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000011','-','')), '猫が椅子の上で寝ています。', 'Con mèo đang ngủ trên ghế.', 'Neko ga isu no ue de neteimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000012','-','')), 'コンビニでコーヒーを買います。', 'Tôi mua cà phê ở cửa hàng tiện lợi.', 'Konbini de koohii wo kaimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000013','-','')), '日本へ行ったことがあります。', 'Tôi đã từng đến Nhật Bản.', 'Nihon e itta koto ga arimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000014','-','')), 'この料理はとてもおいしいです。', 'Món ăn này rất ngon.', 'Kono ryouri wa totemo oishii desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000015','-','')), '図書館で本を読みます。', 'Tôi đọc sách ở thư viện.', 'Toshokan de hon wo yomimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000016','-','')), '明日は日曜日です。', 'Ngày mai là Chủ nhật.', 'Ashita wa nichiyoubi desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000017','-','')), '電車で会社へ行きます。', 'Tôi đến công ty bằng tàu điện.', 'Densha de kaisha e ikimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000018','-','')), '私の家族は四人です。', 'Gia đình tôi có bốn người.', 'Watashi no kazoku wa yonin desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000019','-','')), '日本語は面白いです。', 'Tiếng Nhật thú vị.', 'Nihongo wa omoshiroi desu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000020','-','')), '少し日本語が話せます。', 'Tôi nói được một chút tiếng Nhật.', 'Sukoshi nihongo ga hanasemasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000021','-','')), 'ここで写真を撮ってはいけません。', 'Không được chụp ảnh ở đây.', 'Koko de shashin wo totte wa ikemasen.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000022','-','')), '一緒に昼ご飯を食べませんか。', 'Cùng ăn trưa nhé?', 'Issho ni hirugohan wo tabemasen ka.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000023','-','')), '音楽を聞きながら勉強します。', 'Tôi vừa nghe nhạc vừa học.', 'Ongaku wo kikinagara benkyou shimasu.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000024','-','')), '時間がないから、急ぎましょう。', 'Vì không có thời gian nên nhanh lên nào.', 'Jikan ga nai kara, isogimashou.'),
  (UNHEX(REPLACE('40000000-0000-0000-0000-000000000025','-','')), 'この本は高くないです。', 'Cuốn sách này không đắt.', 'Kono hon wa takakunai desu.');
